project::BackupPolicy Editor::projectBackupPolicy()const{
 project::BackupPolicy p;p.enabled=runtimePreferences_.flag("files.projectBackupEnabled");
 auto number=[this](const char* key,int fallback){try{const auto value=runtimePreferences_.get(key);std::size_t used=0;const auto n=std::stod(value,&used);if(used==value.size()&&std::isfinite(n))return int(std::clamp(n,1.,365.));}catch(...){}return fallback;};
 p.versions=number("files.projectBackupVersions.Number",10);p.days=number("files.projectBackupRetentionDays.Number",30);const auto configured=runtimePreferences_.get("files.projectBackupDirectory.Text");p.directory=configured.empty()?palettePreferencePath().parent_path()/"project-backups":std::filesystem::u8path(configured);return project::normalizeBackupPolicy(std::move(p));
}
void Editor::initializeProjectRollback(){menuCommands_.bind("projectRollback",{[this]{showProjectRollback();},[this]{auto extension=documentPath_.extension().wstring();std::transform(extension.begin(),extension.end(),extension.begin(),[](wchar_t c){return std::towlower(c);});return documentOpen_&&!homeOpen_&&pending_==Pending::None&&!historyGestureBusy()&&projectBackupPolicy().enabled&&!documentPath_.empty()&&extension==L".moonsprite";},{}});}
void Editor::showProjectRollback(){
 const DWORD smokeMode=GetEnvironmentVariableW(L"MOONSPRITE_ROLLBACK_SMOKE",nullptr,0);const bool smokeRequested=smokeMode>0;
 if(smokeMode==2){smoke_=true;pending_=Pending::None;homeOpen_=false;documentOpen_=true;const auto root=assets_.parent_path()/("rollback-smoke-owned-"+std::to_string(GetCurrentProcessId())+"-"+std::to_string(GetTickCount64()));if(std::filesystem::exists(root))throw std::runtime_error("Rollback fixture root exists");std::filesystem::create_directory(root);std::ofstream(root/"test-owned.marker")<<"native rollback smoke";documentPath_=root/"saved.moonsprite";project::BackupPolicy policy{true,10,30,root/"backups"};document=Document(1,1);document.beginStroke({0,0},0xff123456);document.commitStroke();project::saveDocumentAtomic(document,documentPath_,policy);document.beginStroke({0,0},0xff654321);document.commitStroke();project::saveDocumentAtomic(document,documentPath_,policy);runtimePreferences_.set("files.projectBackupEnabled","true");runtimePreferences_.set("files.projectBackupDirectory.Text",root.u8string()+"/backups");refresh();if(!menuCommands_.connected("projectRollback")||!menuCommands_.enabled("projectRollback"))throw std::runtime_error("Rollback actual menu unavailable");SetEnvironmentVariableW(L"MOONSPRITE_ROLLBACK_SMOKE",L"run");if(!menuCommands_.invoke("projectRollback"))throw std::runtime_error("Rollback actual menu invocation failed");return;}

 if(!documentOpen_||homeOpen_||pending_!=Pending::None||historyGestureBusy())return;
 const auto currentPath=documentPath_;const auto identity=document.identity();const auto policy=projectBackupPolicy();if(currentPath.empty()||!policy.enabled)return;
 ProjectRollbackDialog popup(font_,skin_,toolIcons_);popup.setDisplay(display(),false);const auto area=bounds();popup.setBounds({area.center().x-180*uiScale,area.center().y-145*uiScale,360*uiScale,290*uiScale});
 const bool verify=smokeRequested;int smokeStage=0;const auto smokeRevision=document.revision();const auto smokePixels=document.pixels();
 std::vector<project::BackupRecord> records;std::future<std::vector<project::BackupRecord>> listing;std::future<Document> restoring;bool busy=false;ui::Timer poll(16,&popup);
 auto startList=[&]{if(busy)return;busy=true;popup.setState(true,U"正在读取工程备份...");try{listing=std::async(std::launch::async,[currentPath,root=policy.directory]{return project::listProjectBackups(currentPath,root);});}catch(const std::exception& e){busy=false;popup.setState(false,U"无法读取工程备份："+unicodeText(e.what()));}};
 popup.refreshRequested=startList;
 popup.restoreRequested=[&](std::size_t index){if(busy||index>=records.size())return;busy=true;popup.setState(true,U"正在读取并还原工程备份...");try{const auto path=records[index].path;restoring=std::async(std::launch::async,[path]{const project::Limits limits;std::ifstream file(path,std::ios::binary|std::ios::ate);if(!file)throw std::runtime_error("Cannot read project backup");const auto length=file.tellg();if(length<0||std::uint64_t(length)>limits.archiveBytes)throw std::runtime_error("Backup exceeds read budget");auto bytes=std::make_shared<project::Bytes>(std::size_t(length));file.seekg(0);if(!file.read(reinterpret_cast<char*>(bytes->data()),std::streamsize(bytes->size())))throw std::runtime_error("Incomplete backup read");auto imported=project::prepareEditableImport(project::readProjectManifest(bytes,limits));PaletteState palette;palette.entries.clear();palette.slots=std::move(imported.palette.slots);palette.nextId=imported.palette.nextId;palette.columns=imported.palette.columns;for(auto& e:imported.palette.entries)palette.entries.push_back({e.id,std::move(e.name),e.color});auto candidate=Document::fromImported(imported.width,imported.height,std::move(imported.timeline),std::move(palette),std::move(imported.id),std::move(imported.name),std::move(imported.sourceArchive));candidate.setImportedProjectInformation(imported.information);candidate.setImportedReferenceImages(std::move(imported.referenceImages));candidate.setImportedSlices(std::move(imported.slices));candidate.setImportedTimelapse(std::move(imported.timelapse));candidate.setImportedProjectBrushes(std::move(imported.customBrushes));candidate.selectLayer(imported.activeLayerId);candidate.selectFrame(imported.activeFrameId);candidate.setImportedLoop(imported.loop);candidate.setPixelGrid(imported.showPixelGrid,false);candidate.setCustomGrid(imported.showCustomGrid,imported.customGrid,false);if(imported.symmetryCenter)candidate.setSymmetryCenter({imported.symmetryCenter->first,imported.symmetryCenter->second},false);return candidate;});}catch(const std::exception& e){busy=false;popup.setState(false,U"无法回档工程备份："+unicodeText(e.what()));}};
 poll.Tick.connect([&]{if(listing.valid()&&listing.wait_for(std::chrono::milliseconds(0))==std::future_status::ready){try{records=listing.get();popup.showRows(records);busy=false;popup.setState(false,U"");}catch(const std::exception& e){busy=false;popup.showRows({});popup.setState(false,U"无法读取工程备份："+unicodeText(e.what()));}}if(restoring.valid()&&restoring.wait_for(std::chrono::milliseconds(0))==std::future_status::ready){try{auto candidate=restoring.get();if(document.identity()!=identity||documentPath_!=currentPath)throw std::runtime_error("Current project changed");if(!document.rollbackProject(candidate))throw std::runtime_error("Current operation prevents rollback");busy=false;status_=U"已回档工程备份，可通过编辑 - 撤销返回当前版本。";popup.setState(false,U"已回档，可通过撤销返回。");refresh();}catch(const std::exception& e){busy=false;popup.setState(false,U"无法回档工程备份："+unicodeText(e.what()));}}if(verify&&!busy){if(smokeStage==0){if(records.size()!=1)throw std::runtime_error("Rollback actual list missing fixture");smokeStage=1;popup.smokeRefresh();}else if(smokeStage==1){if(records.size()!=1)throw std::runtime_error("Rollback refresh lost real list");{std::ofstream corrupt(records[0].path,std::ios::binary|std::ios::trunc);corrupt<<"owned-invalid-backup";}smokeStage=2;popup.restoreRequested(0);}else if(smokeStage==2){if(popup.state().find(U"无法回档")==std::u32string::npos||document.revision()!=smokeRevision||document.pixels()!=smokePixels)throw std::runtime_error("Rollback read error mutated document or missing error");smokeStage=3;popup.smokeClose();}}});
 startList();poll.start();popup.openWindowInForeground();poll.stop();if(verify&&smokeStage!=3)throw std::runtime_error("Rollback opened smoke incomplete");requestFocus();refresh();
}
